try {
    [System.IO.File]::WriteAllBytes($Target, [System.Convert]::FromBase64String(($Payload -replace '\s','')))

    & node --check $Target
    if ($LASTEXITCODE -ne 0) { throw "The repair v3 script failed JavaScript syntax validation." }

    & node $Target --self-test
    if ($LASTEXITCODE -ne 0) { throw "The repair v3 self-test failed." }

    Write-Host ""
    Write-Host "Inspecting the first 10 current failures without making an API request..." -ForegroundColor Cyan
    & npm run repair:cached-emet -- --plan --limit 10
    if ($LASTEXITCODE -ne 0) { throw "The repair v3 plan failed." }

    Write-Host ""
    Write-Host "P04 targeted final repair v3.0.0 installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupDir"
    Write-Host ""
    Write-Host "Next command:"
    Write-Host "npm run repair:cached-emet -- --limit 20 --concurrency 2 --attempts 2" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "This preserves all accepted caches and repairs only current failures."
}
catch {
    Write-Warning "Installation failed. Restoring the previous repair script..."
    $Backup = Join-Path $BackupDir "repair-cached-emet-failures.js"
    if (Test-Path $Backup) {
        Copy-Item $Backup $Target -Force
    } elseif (Test-Path $Target) {
        Remove-Item $Target -Force
    }
    throw
}
